30	const PROCESSING_FEE = 5;
31	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
32	
33	const BASE_PREMIUMS: Record<string, number> = {
34	  sword: 100,
35	  amulet: 60,
36	  staff: 80,
37	  potion: 40,
38	  rune: 25,
39	  moonstone: 25,
40	};
41	
42	const CURSE_SURCHARGE_RATE = 0.5;
43	
44	const BLOCK_SIZE = 3;
45	const BLOCK_BASE_PREMIUM = 60;
46	
47	const countByType = (items: Item[]): Map<string, number> => {
48	  const counts = new Map<string, number>();
49	  for (const item of items) {
50	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
51	  }
52	  return counts;
53	};
54	
55	// A block is exactly BLOCK_SIZE alike items, charged as one unit.
56	const formsBlock = (count: number): boolean => count === BLOCK_SIZE;
57	
58	const groupBasePremium = (type: string, count: number): number =>
59	  formsBlock(count) ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
60	
61	const policyBasePremium = (items: Item[]): number =>
62	  [...countByType(items)].reduce(
63	    (total, [type, count]) => total + groupBasePremium(type, count),
64	    0,
65	  );
66	
67	// The MHPCO rounds in its own favour: premiums up, payouts down.
68	const roundUpInMHPCOsFavour = (amount: number): number => Math.ceil(amount);
69	
70	// Item-scoped modifiers apply to the affected item's own base premium.
71	const itemSurcharges = (items: Item[]): number =>
72	  items.reduce(
73	    (total, item) =>
74	      item.cursed ? total + BASE_PREMIUMS[item.type] * CURSE_SURCHARGE_RATE : total,
75	    0,
76	  );
77	
78	const quote = (step: Step): QuoteResult => {
79	  const basePremium = policyBasePremium(step.items);
80	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
81	  const modifiedPremium =
82	    basePremium + itemSurcharges(step.items) + firstInsuranceSurcharge;
83	
84	  return {
85	    premium: roundUpInMHPCOsFavour(modifiedPremium + PROCESSING_FEE),
86	  };
87	};
88	
89	export const runScenario = (scenario: Scenario): ScenarioResult => ({
90	  results: scenario.steps.map(quote),
91	});
